const UI="<!doctype html><html lang=\"pt-BR\"><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width, initial-scale=1\"><title>Radar Recife</title><style>\n*{box-sizing:border-box}body{margin:0;background:#f5f5ef;color:#143c34;font:16px/1.5 system-ui}header,main,footer{max-width:1200px;margin:auto;padding:25px}header{display:flex;justify-content:space-between;border-bottom:1px solid #ccd4cc;font-size:12px;letter-spacing:1px}h1{font-size:clamp(42px,7vw,80px);letter-spacing:-4px;line-height:1.05;margin:35px 0 20px}h1 em{font-family:Georgia;font-weight:400;color:#79713b}button,input,select{font:inherit;padding:12px;border:1px solid #b8c8bf;border-radius:9px}button{cursor:pointer;background:#173e35;color:white}button:disabled{opacity:.5}input{min-width:0}a{color:inherit}nav{display:flex;gap:12px;flex-wrap:wrap;margin:25px 0}.info{padding:15px;background:#e5eadf;border-radius:10px;font-size:14px}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(290px,1fr));gap:16px}article{background:white;border:1px solid #d6ded6;padding:22px;border-radius:16px}article p{font-size:14px}small{color:#63756e}.pill{font-size:11px;text-transform:uppercase;letter-spacing:1px;color:#86722e}h3{line-height:1.3}details{margin:25px 0}summary{cursor:pointer;font-weight:700}.source{display:grid;grid-template-columns:1fr 2fr;gap:10px;border-bottom:1px solid #ddd;padding:12px 0;font-size:14px}.source small{grid-column:1/-1}.footer-inner{display:flex;align-items:center;gap:25px;flex-wrap:wrap}footer img{max-width:150px;max-height:65px}#add{display:flex;gap:8px;flex-wrap:wrap}.muted{color:#63756e}#stats{font-size:20px;font-weight:600;margin:20px 0}@media(max-width:600px){header{gap:20px}h1{letter-spacing:-2px}.source{display:block}}\n.share{margin:16px 0 0}.share summary{display:inline-block;padding:9px 13px;border:1px solid #b8c8bf;border-radius:8px;font-size:14px}.share-menu{display:flex;gap:8px;flex-wrap:wrap;margin:10px 0}.share-menu a,.share-menu button{font-size:13px;padding:8px 10px;text-decoration:none;border:1px solid #b8c8bf;border-radius:7px;background:#f5f5ef;color:#143c34}.share small{display:block}dialog{width:min(750px,95vw);max-height:90vh;border:1px solid #bacabd;border-radius:18px;padding:25px;color:#143c34}dialog::backdrop{background:#143c3490}dialog label{display:block;margin:15px 0}textarea{width:100%;display:block;font:15px/1.5 system-ui;padding:12px;border:1px solid #b8c8bf;border-radius:8px;resize:vertical}.consent{font-size:14px}.draft-open{margin:12px 0}.consent input{margin-right:8px}</style><header><b>CODESINFO / REC’N’PLAY</b><span>GRUPO 02 · RADAR EDITORIAL</span></header><main><span class=\"pill\">RECIFE · FONTES PÚBLICAS · ÚLTIMOS 7 DIAS</span><h1>A cidade muda.<br><em>A pauta aparece.</em></h1><p>Um painel para acompanhar atos oficiais, economia local e cultura. Cadastre links, atualize as fontes e leve os achados para a apuração.</p><div class=\"info\">Coleta real, sem notícias inventadas. A data de publicação vem da fonte. Itens sem data ou sem relação explícita com Recife ficam separados para revisão. Esta primeira versão coleta uma amostra de links por fonte: não equivale à cobertura integral de cada site. <b id=\"schedule\">Atualização pelo botão e rotina externa provisória diária, por 7 dias, aproximadamente às 8h de Recife a partir de 14/11/2026. A execução agendada ainda não foi verificada.</b></div><nav><button id=\"refresh\">Atualizar fontes agora</button><input id=\"search\" placeholder=\"Pesquisar assunto\"><select id=\"category\"><option value=\"\">Todas as categorias</option><option>Oficial</option><option>Empresarial</option><option>Cultura</option></select></nav><div id=\"progress\" role=\"status\"></div><div id=\"stats\"></div><section class=\"grid\" id=\"items\"></section><details><summary>Itens que precisam de conferência</summary><p class=\"muted\">Data ausente, edição em PDF ou relação com Recife não identificada. Não entram na contagem de notícias recentes.</p><section id=\"review\" class=\"grid\"></section></details><details open><summary>Fontes e saúde da coleta</summary><div id=\"sources\"></div><h3>Adicionar uma fonte pública</h3><form id=\"add\"><input name=\"name\" required placeholder=\"Nome da fonte\"><input name=\"url\" required type=\"url\" placeholder=\"https://...\"><select name=\"category\"><option>Oficial</option><option>Empresarial</option><option>Cultura</option></select><input name=\"code\" type=\"password\" required placeholder=\"Código da oficina\"><button>Cadastrar</button></form><small>As fontes e os resultados deste protótipo são compartilhados com o grupo. Não cadastre links privados.</small></details><dialog id=\"editor\"><form method=\"dialog\"><button style=\"float:right\">Fechar</button></form><h2>Prepare uma versão. Revise antes de usar.</h2><p id=\"draft-source\"></p><button id=\"draft-fetch\" type=\"button\">Buscar corpo da matéria original</button><p id=\"draft-extraction\" role=\"status\"></p><label>Material de referência<textarea id=\"draft-input\" rows=\"8\"></textarea></label><small>Busque o corpo da matéria ou cole o texto original. Confira a extração antes de gerar. Bloqueios e paywalls não são contornados. Não inclua informações privadas.</small><label>Formato<select id=\"draft-format\"><option value=\"instagram\">Instagram</option><option value=\"site\">Matéria para site</option><option value=\"curta\">Versão curta · até 280 caracteres</option></select></label><label>Código da oficina<input id=\"draft-code\" type=\"password\" placeholder=\"Código recebido no Slack\"></label><label class=\"consent\"><input id=\"draft-consent\" type=\"checkbox\"> Autorizo enviar este texto e o link da fonte à OpenAI para gerar um rascunho. Li o material e posso usá-lo.</label><button id=\"draft-generate\" type=\"button\">Gerar rascunho</button><p id=\"draft-status\" role=\"status\"></p><label>Rascunho editável<textarea id=\"draft-output\" rows=\"10\" placeholder=\"O resultado aparece aqui para você revisar.\"></textarea></label><small id=\"draft-count\"></small><button id=\"draft-copy\" type=\"button\">Copiar versão revisada</button><p>Confirme fatos, datas, números e atribuição no original. Nada é publicado automaticamente. A versão curta conta apenas o texto; o link da fonte vai separado.</p></dialog></main><footer>\n    <div class=\"footer-inner\">\n      <p class=\"credit\">site prototipado durante a oficina Da Ideia ao Protótipo com IA no jornalismo.</p>\n      <div class=\"logos\">\n        <a href=\"https://codesinfo.com.br/\" aria-label=\"Codesinfo\"><img class=\"codesinfo\" src=\"assets/codesinfo.png\" alt=\"Codesinfo\" width=\"687\" height=\"172\"></a>\n        <a href=\"https://recnplay.pe/\" aria-label=\"REC’n’Play\"><img class=\"recnplay\" src=\"assets/recnplay.png\" alt=\"REC’n’Play\" width=\"500\" height=\"500\"></a>\n        <div class=\"sponsor\"><span class=\"sponsor-label\">Patrocínio: Google News Initiative</span><a href=\"https://newsinitiative.withgoogle.com/\"><img class=\"gni\" src=\"assets/gni.svg\" alt=\"Google News Initiative\" width=\"247\" height=\"28\"></a></div>\n      </div>\n    </div>\n  </footer><script>\nlet sources=[],results=[];const $=id=>document.getElementById(id),esc=s=>String(s||'').replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c]));\nasync function api(url,opts){const r=await fetch(url,opts);const d=await r.json();if(!r.ok)throw Error(d.error||r.status);return d}\nfunction card(x){return '<article><span class=\"pill\">'+esc(x.category)+' · '+esc(x.source)+'</span><h3><a target=\"_blank\" rel=\"noopener\" href=\"'+esc(x.url)+'\">'+esc(x.title)+'</a></h3><small>'+esc(x.published?new Date(x.published).toLocaleDateString('pt-BR'):'Data não identificada')+'</small><p>'+esc(x.description||'Confira o conteúdo completo na fonte.')+'</p>'+(x.reason?'<p class=\"muted\">'+esc(x.reason)+'</p>':'')+'<button class=\"draft-open\" type=\"button\" data-draft=\"'+esc(x.url)+'\">Criar versão com IA</button>'+shareMenu(x)+'</article>'}\nfunction draw(){const q=$('search').value.toLowerCase(),cat=$('category').value;let all=results.flatMap(r=>r.items||[]),unique=[...new Map(all.map(x=>[x.url,x])).values()];const match=x=>(!cat||x.category===cat)&&JSON.stringify(x).toLowerCase().includes(q);let good=unique.filter(x=>x.eligible&&match(x)).sort((a,b)=>b.published.localeCompare(a.published)),review=unique.filter(x=>!x.eligible&&match(x));$('stats').textContent=good.length+' achados recentes · '+results.filter(r=>r.checkedAt).length+' fontes consultadas';$('items').innerHTML=good.map(card).join('')||'<p>Nenhum achado confirmado nesta coleta. Veja o estado das fontes abaixo; ausência de resultado não significa ausência de notícias.</p>';$('review').innerHTML=review.map(card).join('');$('sources').innerHTML=sources.map(s=>{let r=results.find(r=>r.id===s.id);return '<div class=\"source\"><b>'+esc(s.name)+'</b><a href=\"'+esc(s.url)+'\" target=\"_blank\" rel=\"noopener\">'+esc(s.url)+'</a><small>'+esc(r?(r.error||r.note||'Coleta concluída')+' · '+new Date(r.checkedAt).toLocaleString('pt-BR'):'Ainda não consultada')+'</small></div>'}).join('')}\nfunction shareMenu(x){const u=encodeURIComponent(x.url),t=encodeURIComponent(x.title);return '<details class=\"share\"><summary>Compartilhar matéria</summary><div class=\"share-menu\"><a target=\"_blank\" rel=\"noopener noreferrer\" href=\"https://wa.me/?text='+t+'%20'+u+'\">WhatsApp</a><a target=\"_blank\" rel=\"noopener noreferrer\" href=\"https://www.linkedin.com/sharing/share-offsite/?url='+u+'\">LinkedIn</a><a target=\"_blank\" rel=\"noopener noreferrer\" href=\"https://www.facebook.com/sharer/sharer.php?u='+u+'\">Facebook</a><a target=\"_blank\" rel=\"noopener noreferrer\" href=\"https://twitter.com/intent/tweet?text='+t+'&url='+u+'\">X</a><button type=\"button\" data-copy=\"'+esc(x.url)+'\">Copiar link</button><button type=\"button\" data-share=\"'+esc(x.url)+'\" data-title=\"'+esc(x.title)+'\">Outros apps</button></div><small>Você revisa e confirma o envio na rede escolhida. Nada é publicado automaticamente.</small><span class=\"share-status\" role=\"status\"></span></details>'}\ndocument.addEventListener('click',async e=>{const b=e.target.closest('button[data-copy],button[data-share]');if(!b)return;const status=b.closest('.share').querySelector('.share-status');try{if(b.dataset.share&&navigator.share){await navigator.share({title:b.dataset.title,url:b.dataset.share});status.textContent='Compartilhamento aberto no dispositivo.'}else{await navigator.clipboard.writeText(b.dataset.copy||b.dataset.share);status.textContent='Link copiado. Cole na rede de sua preferência.'}}catch(err){status.textContent=err.name==='AbortError'?'Compartilhamento cancelado.':'Não foi possível compartilhar. Abra a matéria e copie seu endereço.'}});\nlet selectedDraft=null;document.addEventListener('click',e=>{const b=e.target.closest('[data-draft]');if(!b)return;selectedDraft=results.flatMap(r=>r.items||[]).find(x=>x.url===b.dataset.draft);if(!selectedDraft)return;$('draft-source').textContent='Fonte: '+selectedDraft.source+' · '+selectedDraft.url;$('draft-input').value='';$('draft-extraction').textContent='O título e o resumo não substituem a matéria. Informe o código e busque o texto original, ou cole-o abaixo.';$('draft-output').value='';$('draft-consent').checked=false;$('draft-status').textContent='';$('draft-count').textContent='';$('editor').showModal()});\n$('draft-fetch').onclick=async()=>{const url=selectedDraft.url;$('draft-fetch').disabled=true;$('draft-extraction').textContent='Buscando texto na fonte original…';try{const d=await api('/api/article',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({url,code:$('draft-code').value})});if(selectedDraft.url!==url)return;$('draft-input').value=d.text;$('draft-consent').checked=false;$('draft-extraction').textContent=d.method+' · '+d.characters+' caracteres. '+d.warning}catch(e){$('draft-extraction').textContent=e.message}finally{$('draft-fetch').disabled=false}};\n$('draft-generate').onclick=async()=>{if(!$('draft-consent').checked){$('draft-status').textContent='Confirme o envio à OpenAI antes de gerar.';return}$('draft-generate').disabled=true;$('draft-status').textContent='Gerando rascunho com IA…';try{const d=await api('/api/rewrite',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({text:$('draft-input').value,url:selectedDraft.url,source:selectedDraft.source,format:$('draft-format').value,code:$('draft-code').value,consent:true})});$('draft-output').value=d.text;$('draft-status').textContent='Rascunho gerado. Revise antes de copiar.';$('draft-output').dispatchEvent(new Event('input'))}catch(e){$('draft-status').textContent=e.message}finally{$('draft-generate').disabled=false}};\n$('draft-output').oninput=()=>{const n=Array.from($('draft-output').value).length;$('draft-count').textContent=n+' caracteres'+($('draft-format').value==='curta'&&n>280?' · acima de 280: reduza antes de copiar.':'')};\n$('draft-copy').onclick=async()=>{let text=$('draft-output').value;if(!text.trim()){ $('draft-status').textContent='Gere ou escreva uma versão primeiro.';return}if($('draft-format').value==='curta'&&Array.from(text).length>280){$('draft-status').textContent='Reduza a versão curta para até 280 caracteres.';return}try{await navigator.clipboard.writeText(text+'\\n\\nFonte: '+selectedDraft.source+'\\n'+selectedDraft.url);$('draft-status').textContent='Versão revisada e fonte copiadas.'}catch{$('draft-status').textContent='Selecione e copie o texto manualmente.'}};\nasync function load(){sources=await api('/api/sources');results=await api('/api/results');draw()}\n$('refresh').onclick=async()=>{ $('refresh').disabled=true;for(let i=0;i<sources.length;i++){$('progress').textContent='Consultando '+(i+1)+'/'+sources.length+': '+sources[i].name;try{let r=await api('/api/refresh?id='+encodeURIComponent(sources[i].id));results=results.filter(x=>x.id!==r.id);results.push(r);draw()}catch(e){$('progress').textContent=e.message}}$('progress').textContent='Rodada concluída. Confira os avisos de cada fonte.';$('refresh').disabled=false};$('search').oninput=draw;$('category').onchange=draw;$('add').onsubmit=async e=>{e.preventDefault();let d=Object.fromEntries(new FormData(e.target));try{await api('/api/sources',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(d)});e.target.reset();await load()}catch(e){alert(e.message)}};load().catch(e=>$('progress').textContent=e.message);\n</script></html>";
